def solve():
    import sys
    t = int(sys.stdin.readline())
    for _ in range(t):
        s = sys.stdin.readline().strip()
        count_A = s.count('A')
        count_B = s.count('B')
        count_C = s.count('C')
        if count_A == count_C or (count_A - count_C) % 2 == 0 and count_B >= abs(count_A - count_C):
            print("YES")
        else:
            print("NO")

solve()
